type Reader interface { Read(p []byte) (n int, err error) } // contract only
type fileReader struct{ f *os.File }                        // state lives here

func NewReader(path string) (Reader, error) {               // returns the contract
    f, err := os.Open(path)
    if err != nil {
        return nil, err
    }
    return &fileReader{f: f}, nil
}

func (r *fileReader) Read(p []byte) (int, error) { return r.f.Read(p) }

