type ordered interface { ~int | ~float64 | ~string }  // a set of types

func Max[T ordered](xs []T) T {   // monomorphised: static dispatch
    m := xs[0]
    for _, x := range xs[1:] {
        if x > m {
            m = x
        }
    }
    return m
}
